#include <iostream>
int main() {
    int code{};
    if (!(std::cin >> code)) { std::cout << "invalid\n"; return 0; }
    switch (code) {
        case 1: std::cout << "open\n"; break;
        case 2: std::cout << "save\n"; break;
        default: std::cout << "unknown\n"; break;
    }
}

