#include <iostream>
int main() {
    int score{};
    if (!(std::cin >> score)) { std::cout << "invalid\n"; return 0; }
    std::cin >> std::ws;
    if (!std::cin.eof() || score < 0 || score > 100) { std::cout << "invalid\n"; return 0; }
    if (score >= 85) { std::cout << "distinction\n"; }
    else if (score >= 60) { std::cout << "pass\n"; }
    else { std::cout << "retry\n"; }
}
